#!/usr/bin/env python3
"""Realism report for a fleet generated by ml-model/generate_telecom_fleet_v3.py.

Checks the failure model against the questions a reviewer asks, using the incident log written
next to the CSV as ground truth:

  * how many of a router's dependents are affected per incident, by mode, by day and night
  * "N machines behind one router are anomalous and the router is normal - how?"
  * "every machine behind a router is anomalous - what does that mean?"
  * "the router is anomalous and its machines are fine - how?"
  * how long a failure takes to propagate, and whether every unreachable reading has a cause

Every anomalous-dependents-with-a-normal-router moment is classified (recovery tail after an
incident, or coincident machine-local faults); nothing is left unexplained silently. Read-only.

    python3 scripts/failure_model_report.py --data data/telecom_fleet_v3.csv
"""
import argparse
import json
import sys
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parent.parent
DAY = range(8, 20)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--data", type=Path, default=ROOT / "data" / "telecom_fleet_v3.csv")
    ap.add_argument("--many", type=int, default=15, help='"many dependents" for the first question')
    ap.add_argument("--tail", type=int, default=4, help="readings after an incident counted as its recovery")
    args = ap.parse_args()
    import pandas as pd

    log_path = args.data.with_suffix(".incidents.json")
    if not args.data.exists() or not log_path.exists():
        print(f"need {args.data} and {log_path} (written by generate_telecom_fleet_v3.py)", file=sys.stderr)
        return 1
    log = json.loads(log_path.read_text())
    n, step = log["readings_per_machine"], log["step_seconds"]
    dep_of = log["depends_on"]
    routers = sorted(log["incidents"])
    n_dep = {r: sum(1 for v in dep_of.values() if v == r) for r in routers}
    r_idx = {r: k for k, r in enumerate(routers)}

    anom = np.zeros((len(routers), n), dtype=np.int16)        # anomalous dependents per router, per step
    unreach = np.zeros((len(routers), n), dtype=np.int16)
    local = np.zeros((len(routers), n), dtype=np.int16)        # dependents anomalous for a local cause
    r_lab = np.zeros((len(routers), n), dtype=np.int8)
    r_reach = np.ones((len(routers), n), dtype=np.int8)
    first_hit = {}                                             # (router, incident start) -> first dependent step
    ts_index, rows = {}, 0
    cols = ["timestamp", "machine", "label", "anomaly_type", "root_cause", "reachable"]
    for chunk in pd.read_csv(args.data, usecols=cols, chunksize=1_000_000,
                             dtype={"anomaly_type": str, "root_cause": str}, keep_default_na=False):
        rows += len(chunk)
        if not ts_index:
            first = chunk.loc[chunk["machine"] == chunk["machine"].iloc[0], "timestamp"]
            if len(first) < n:            # first machine spans chunks: index from the incident log instead
                first = None
            if first is not None:
                ts_index = {t: i for i, t in enumerate(first)}
        if not ts_index:
            from datetime import datetime, timedelta
            t0 = datetime.fromisoformat(log["start"])
            ts_index = {str(t0 + timedelta(seconds=step * i)): i for i in range(n)}
        t = chunk["timestamp"].map(ts_index).to_numpy()
        mach = chunk["machine"].to_numpy()
        lab = chunk["label"].to_numpy().astype(np.int8)
        rc = chunk["root_cause"].to_numpy()
        reach = chunk["reachable"].to_numpy().astype(np.int8)
        is_r = np.isin(mach, routers)
        for r in routers:
            sel = mach == r
            if sel.any():
                r_lab[r_idx[r], t[sel]] = lab[sel]
                r_reach[r_idx[r], t[sel]] = reach[sel]
        dep_router = np.array([dep_of.get(m, "") for m in mach], dtype=object)
        for r in routers:
            sel = (dep_router == r) & ~is_r
            if not sel.any():
                continue
            k = r_idx[r]
            np.add.at(anom[k], t[sel & (lab == 1)], 1)
            np.add.at(unreach[k], t[sel & (reach == 0)], 1)
            np.add.at(local[k], t[sel & (lab == 1) & (rc != r)], 1)
        print(f"  read {rows:,} rows", end="\r", flush=True)
    print(f"  read {rows:,} rows        ")

    # ground-truth incident state per router and step
    state = np.zeros((len(routers), n), dtype=np.int8)          # 0 none, 1 gray, 2 down, 3 control
    after = np.zeros((len(routers), n), dtype=bool)             # recovery tail
    code = {"gray": 1, "down": 2, "control_plane": 3}
    incs = []
    for r in routers:
        k = r_idx[r]
        for inc in log["incidents"][r]:
            s, e = inc["start"], inc["end"]
            state[k, s:e] = code[inc["mode"]]
            after[k, e:min(n, e + args.tail)] = True
            hour = int(inc["start_ts"][11:13])
            seg = anom[k, s:min(n, e + args.tail)] - local[k, s:min(n, e + args.tail)]
            hit = np.flatnonzero(seg > 0)
            incs.append({"router": r, "mode": inc["mode"], "day": hour in DAY, "dur": e - s,
                         "peak": float(seg.max()) / max(n_dep[r], 1) if len(seg) else 0.0,
                         "unreach": float(unreach[k, s:e].max()) / max(n_dep[r], 1) if e > s else 0.0,
                         "lag": int(hit[0]) if len(hit) else None})

    def pct(a, q):
        return float(np.percentile(a, q)) if len(a) else float("nan")

    print("\n== 1. Incidents (ground truth) ==")
    for md in ("gray", "down", "control_plane"):
        d = [i["dur"] for i in incs if i["mode"] == md]
        if d:
            print(f"  {md:<14} {len(d):>5}   duration median {pct(d, 50) * step / 60:.1f} min, "
                  f"p95 {pct(d, 95) * step / 60:.1f} min")

    print("\n== 2. Share of a router's dependents affected at the incident's peak ==")
    print(f"  {'mode':<14} {'when':<6} {'n':>5} {'min':>6} {'median':>7} {'max':>6}")
    for md in ("gray", "down", "control_plane"):
        for day in (True, False):
            p = [i["peak"] for i in incs if i["mode"] == md and i["day"] == day]
            if p:
                print(f"  {md:<14} {'day' if day else 'night':<6} {len(p):>5} {min(p):>6.0%} "
                      f"{pct(p, 50):>7.0%} {max(p):>6.0%}")

    un = [i["unreach"] for i in incs if i["mode"] == "down"]
    if un:
        print(f"  hard down, dependents UNREACHABLE at the peak: min {min(un):.0%}, median {pct(un, 50):.0%}"
              f" (below 100% affected only where a machine was already failing for its own reason)")

    print("\n== 3. Propagation delay (incident start -> first affected dependent) ==")
    for md in ("gray", "down"):
        lags = [i["lag"] for i in incs if i["mode"] == md and i["lag"] is not None]
        if lags:
            print(f"  {md:<6} median {pct(lags, 50) * step:.0f} s, range {min(lags) * step}-{max(lags) * step} s")

    print(f"\n== 4. \"{args.many}+ machines behind one router are anomalous and the router is normal\" ==")
    many = anom >= args.many
    q1 = many & (r_lab == 0)
    in_tail = q1 & after
    coinc = q1 & ~after
    print(f"  router-steps with {args.many}+ anomalous dependents: {int(many.sum()):,}")
    print(f"  ... of which the router is labelled normal:         {int(q1.sum()):,}")
    print(f"      in the recovery tail just after an incident:     {int(in_tail.sum()):,}")
    print(f"      not explained by an incident (coincident local faults): {int(coinc.sum()):,}")

    print("\n== 5. \"every machine behind a router is anomalous\" ==")
    full = np.zeros_like(anom, dtype=bool)
    for r in routers:
        full[r_idx[r]] = anom[r_idx[r]] >= n_dep[r]
    for code_v, md in ((2, "down"), (1, "gray"), (0, "no incident")):
        c = int((full & (state == code_v)).sum())
        if c or code_v == 2:
            print(f"  during {md:<12} {c:>7,}")
    tail_full = int((full & (state == 0) & after).sum())
    if tail_full:
        print(f"  (of the 'no incident' ones, in a recovery tail: {tail_full:,})")
    unr_all = int(((unreach > 0) & (state != 2) & ~after).sum())
    print(f"  unreachable dependents outside any hard-down incident or its tail: {unr_all:,}")

    print("\n== 6. \"the router is anomalous and its machines are fine\" ==")
    q3 = (r_lab == 1) & (anom - local == 0)
    for code_v, md in ((3, "control_plane (data plane unaffected)"), (1, "gray"), (2, "down")):
        c = int((q3 & (state == code_v)).sum())
        tot = int(((r_lab == 1) & (state == code_v)).sum())
        if tot:
            print(f"  {md:<40} {c:>7,} of {tot:,} router-anomalous steps")
    gray_q3 = q3 & (state == 1)
    if gray_q3.any():
        onset = np.zeros_like(gray_q3)
        for r in routers:
            for inc in log["incidents"][r]:
                if inc["mode"] == "gray":
                    onset[r_idx[r], inc["start"]:inc["start"] + 7] = True
        print(f"    gray, within the first 3 min (propagation lag): {int((gray_q3 & onset).sum()):,}")
        print(f"    gray, later (impact below materiality: low traffic or mild loss): "
              f"{int((gray_q3 & ~onset).sum()):,}")

    print("\nReading it: anomalous dependents behind a router that is labelled normal happen only in the")
    print("short recovery tail after its incident (or when unrelated local faults coincide); every")
    print("machine behind a router failing at once is a hard-down incident, where monitoring sees the")
    print("children as unreachable; a busy router with healthy machines is a control-plane event, or")
    print("a gray failure that is still propagating or too mild for the current traffic.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
